syarah:
[
  {
    "name": "Al-Mustakhraj 'ala Sahih al-Bukhari",
    "author": "Abu Nu'aim al-Asbahani",
    "desc": "Kitab hadits yang memuat sanad-sanad lain untuk hadits-hadits yang ada dalam Shahih al-Bukhari."
  },
  {
    "name": "Al-Sunan",
    "author": "Sa'id bin Mansur",
    "desc": "Kumpulan hadits dan atsar sahabat yang disusun berdasarkan bab-bab fiqih oleh ulama salaf."
  },
  {
    "name": "Al-Sunan",
    "author": "Al-Athram",
    "desc": "Koleksi hadits yang diriwayatkan oleh murid Imam Ahmad bin Hanbal dengan fokus pada hukum syariat."
  },
  {
    "name": "Musnad al-Harith",
    "author": "Al-Harith bin Abi Usamah",
    "desc": "Kitab musnad kuno yang mengumpulkan hadits berdasarkan nama sahabat yang meriwayatkannya."
  },
  {
    "name": "Musnad al-Ruyani",
    "author": "Muhammad bin Harun al-Ruyani",
    "desc": "Kitab hadits yang disusun berdasarkan urutan nama-nama sahabat Nabi SAW."

